// Extract several 1-star reviews currently rendered
const reviews = await browserjs(tabId, () => {
  // Let's get the text around the reviews
  const reviewContainers = Array.from(document.querySelectorAll('div[jscontroller], div[data-review-id], div')).filter(el => {
    return el.textContent?.includes('Rated 1.0 out of 5');
  });
  return reviewContainers.map(c => c.innerText).slice(0, 5);
});
console.log("Reviews count:", reviews.length);
